<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { listAdmin } from "../../api/admin";
import { approveSupplierQuality, closeSpcException, completeSpcAction, confirmQualityCost, confirmSpcException, createCustomerClaim, createQualityCost, createSpc, createSpcAction, listCustomerClaimSources, listCustomerClaims, listQualityCosts, listSpc, listSupplierQuality, listSupplierQualitySources, rejectSupplierQuality, resumeSpcException, retestSpcException, saveSpcContainment, saveSpcRootCause, saveSupplierQuality, transitionCustomerClaim } from "../../api/advanced";
import { useMasterOptions } from "../../composables/useMasterOptions";
import { useClientPagination } from "../../composables/useClientPagination";
import { statusLabel, tagTypeOf } from "../../utils/labels";
type Row = Record<string, any>;
const spc = ref<Row[]>([]); const supplierQuality = ref<Row[]>([]); const costs = ref<Row[]>([]); const claims = ref<Row[]>([]); const claimSources = ref<Row[]>([]); const loading = ref(false); const saving = ref(false); const dialog = ref(""); const exceptionDialog = ref(false); const selectedException = ref<Row | null>(null); const selectedSupplier = ref<Row | null>(null); const selectedClaim = ref<Row | null>(null); const claimWorkflowVisible = ref(false); const claimSourcesLoading = ref(false); const supplierSources = ref<Row[]>([]); const supplierSourcesVisible = ref(false); const supplierReviewVisible = ref(false); const supplierReviewAction = ref<"approve" | "reject">("approve"); const supplierReviewComment = ref(""); const supplierSourcesLoading = ref(false); const users = ref<Array<{ label: string; value: string }>>([]); const { customers, suppliers, materials, loadOptions } = useMasterOptions();
const activeTab = ref("spc");
const { pagedRows: spcRows, page: spcPage, pageSize: spcPageSize, total: spcTotal, updatePageSize: updateSpcPageSize } = useClientPagination(spc);
const { pagedRows: supplierQualityRows, page: supplierQualityPage, pageSize: supplierQualityPageSize, total: supplierQualityTotal, updatePageSize: updateSupplierQualityPageSize } = useClientPagination(supplierQuality);
const { pagedRows: costRows, page: costPage, pageSize: costPageSize, total: costTotal, updatePageSize: updateCostPageSize } = useClientPagination(costs);
const { pagedRows: claimRows, page: claimPage, pageSize: claimPageSize, total: claimTotal, updatePageSize: updateClaimPageSize } = useClientPagination(claims);
const spcForm = reactive({ material_id: "", metric: "", sample_value: 0, lsl: null as number | null, usl: null as number | null, cpk: null as number | null }); const supplierForm = reactive({ supplier_id: "", period: new Date().toISOString().slice(0, 7), inspection_count: 0, defect_count: 0, score: 0, note: "" }); const costForm = reactive({ period: new Date().toISOString().slice(0, 7), cost_type: "internal_failure", amount: 0, source_type: "", source_id: "", note: "" }); const claimForm = reactive({ customer_id: "", source_type: "sales_delivery", source_id: "", title: "", amount: 0 }); const claimWorkflowForm = reactive({ action: "investigating", owner_id: "", due_date: new Date().toISOString().slice(0, 10), root_cause: "", resolution: "", review_evidence: "", review_comment: "", approved_amount: 0, closure_evidence: "" });
const confirmForm = reactive({ severity: "major", disposition: "rework", owner_id: "", due_date: new Date().toISOString().slice(0, 10) });
const containmentForm = reactive({ containment_action: "" });
const rootCauseForm = reactive({ root_cause: "" });
const actionForm = reactive({ action_type: "corrective", description: "", owner_id: "", due_date: new Date().toISOString().slice(0, 10) });
const completionEvidence = reactive<Record<string, string>>({});
const retestForm = reactive({ sample_value: null as number | null });
const closeForm = reactive({ evidence: "" });
const controlStatusLabels: Record<string, string> = { in_control: "受控", out_of_control: "失控", active: "启用", inactive: "停用" };
const workflowStatusLabels: Record<string, string> = { normal: "正常监控", pending_review: "待确认", containment: "临时遏制", root_cause: "原因分析", corrective_action: "整改中", retest: "待复验", reopened: "复验未通过", closed: "已关闭" };
const qualityCostTypeLabels: Record<string, string> = { prevention: "预防成本", appraisal: "鉴定成本", internal_failure: "内部失败成本", external_failure: "外部失败成本" };
const qualityCostSourceTypeLabels: Record<string, string> = { inspection: "检验单", nonconformance: "NCR", supplier_quality: "供应商质量", customer_claim: "客户索赔" };
const qualityCostStatusLabels: Record<string, string> = { estimated: "自动估算", confirmed: "已确认" };
const claimSourceTypeLabels: Record<string, string> = { sales_delivery: "销售出库", sales_return: "销售退货", inspection: "客户检验单", ncr: "NCR" };
const financeExpenseStatusLabels: Record<string, string> = { draft: "财务待审核", approved: "财务已审核", settled: "财务已结算" };
function unwrap(response: any) { if (response?.data?.code !== 0) throw new Error(response?.data?.msg || "质量接口返回失败"); return response.data.data; }
function materialLabel(id: unknown) { const value = String(id || ""); return materials.value.find((option) => option.value === value)?.label || value || "-"; }
function supplierLabel(id: unknown) { const value = String(id || ""); const label = suppliers.value.find((option) => option.value === value)?.label; return label?.replace(/（[^（）]*）$/, "") || value || "-"; }
function defectRateLabel(value: unknown) { return `${(Number(value || 0) * 100).toFixed(2)}%`; }
function qualityCostTypeLabel(value: unknown) { return qualityCostTypeLabels[String(value || "")] || String(value || "-"); }
function qualityCostSourceTypeLabel(value: unknown) { return qualityCostSourceTypeLabels[String(value || "")] || (value ? String(value) : "手工录入"); }
function qualityCostStatusLabel(value: unknown) { return qualityCostStatusLabels[String(value || "")] || String(value || "-"); }
function customerLabel(id: unknown) { const value = String(id || ""); return customers.value.find((option) => option.value === value)?.label || value || "-"; }
function claimSourceTypeLabel(value: unknown) { return claimSourceTypeLabels[String(value || "")] || String(value || "-"); }
function financeExpenseStatusLabel(value: unknown) { return financeExpenseStatusLabels[String(value || "")] || (value ? String(value) : "未生成"); }
function aggregationSourceLabel(value: unknown) { return value === "purchase_inspection" ? "采购检验自动汇总" : "兼容手工数据"; }
function capaStatusLabel(value: unknown) { return ({ not_required: "无需 CAPA", pending: "审核后触发 CAPA", open: "CAPA 待调查", investigating: "CAPA 整改中", closed: "CAPA 已关闭" } as Record<string, string>)[String(value || "")] || String(value || "-"); }
function capaStatusTagType(value: unknown) { return ({ not_required: "success", pending: "warning", open: "danger", investigating: "warning", closed: "info" } as Record<string, string>)[String(value || "")] || "info"; }
function controlStatusLabel(status: unknown) { const value = String(status || ""); return controlStatusLabels[value] || value || "-"; }
function controlStatusTagType(status: unknown) {
  const value = String(status || "");
  if (["in_control", "active"].includes(value)) return "success";
  if (value === "out_of_control") return "danger";
  if (value === "inactive") return "warning";
  return "info";
}
function workflowStatusLabel(status: unknown) { const value = String(status || ""); return workflowStatusLabels[value] || value || "-"; }
function workflowStatusTagType(status: unknown) { return ({ pending_review: "danger", containment: "warning", root_cause: "warning", corrective_action: "primary", retest: "info", reopened: "danger", closed: "success", normal: "success" } as Record<string, string>)[String(status || "")] || "info"; }
function ownerOptions() { return users.value; }
async function load() { loading.value = true; try { const [spcRows, supplierRows, costRows, claimRows, userRows] = await Promise.all([listSpc().then(unwrap), listSupplierQuality().then(unwrap), listQualityCosts().then(unwrap), listCustomerClaims().then(unwrap), listAdmin("users").then(unwrap)]); spc.value = spcRows; supplierQuality.value = supplierRows; costs.value = costRows; claims.value = claimRows; users.value = (userRows || []).filter((user: Row) => user.status === "active").map((user: Row) => ({ label: `${user.display_name}（${user.username}）`, value: user.id })); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "质量分析加载失败"); } finally { loading.value = false; } }
async function saveAction(action: () => Promise<any>, message: string) { saving.value = true; try { unwrap(await action()); ElMessage.success(message); dialog.value = ""; await load(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "保存失败"); } finally { saving.value = false; } }
function open(kind: string) { dialog.value = kind; if (kind === "supplier") Object.assign(supplierForm, { supplier_id: suppliers.value[0]?.value || "", period: new Date().toISOString().slice(0, 7), inspection_count: 0, defect_count: 0, score: 0, note: "" }); if (kind === "claim") { Object.assign(claimForm, { customer_id: customers.value[0]?.value || "", source_type: "sales_delivery", source_id: "", title: "", amount: 0 }); loadClaimSources(); } }
async function loadClaimSources() { claimSourcesLoading.value = true; try { claimSources.value = unwrap(await listCustomerClaimSources(claimForm.source_type, claimForm.customer_id)) || []; } catch (error) { ElMessage.error(error instanceof Error ? error.message : "索赔来源加载失败"); } finally { claimSourcesLoading.value = false; } }
async function saveSpcForm() { if (!spcForm.material_id || !spcForm.metric) return ElMessage.warning("请填写物料和检测指标"); await saveAction(() => createSpc(spcForm), "SPC 样本已保存"); Object.assign(spcForm, { sample_value: 0, lsl: null, usl: null, cpk: null }); }
function openSpcException(row: Row) { if (!row.exception) return; Object.keys(completionEvidence).forEach((key) => delete completionEvidence[key]); selectedException.value = row.exception; confirmForm.severity = row.exception.severity || "major"; confirmForm.disposition = row.exception.disposition || "rework"; confirmForm.owner_id = row.exception.owner_id || ""; confirmForm.due_date = row.exception.due_date || new Date().toISOString().slice(0, 10); containmentForm.containment_action = row.exception.containment_action || ""; rootCauseForm.root_cause = row.exception.root_cause || ""; actionForm.owner_id = row.exception.owner_id || ""; actionForm.due_date = row.exception.due_date || new Date().toISOString().slice(0, 10); retestForm.sample_value = null; closeForm.evidence = row.exception.closure_evidence || ""; exceptionDialog.value = true; }
async function saveExceptionAction(action: () => Promise<any>, message: string) { const exceptionId = selectedException.value?.id; saving.value = true; try { const result = unwrap(await action()); ElMessage.success(message); await load(); if (exceptionId) { const latest = spc.value.find((row) => row.exception?.id === exceptionId)?.exception; if (latest) selectedException.value = latest; } return result; } catch (error) { ElMessage.error(error instanceof Error ? error.message : "SPC 异常处理失败"); return null; } finally { saving.value = false; } }
async function confirmException() { if (!selectedException.value || !confirmForm.owner_id || !confirmForm.due_date) return ElMessage.warning("请填写责任人和整改期限"); await saveExceptionAction(() => confirmSpcException(selectedException.value!.id, confirmForm), "异常已确认，进入临时遏制"); }
async function saveContainment() { if (!selectedException.value || containmentForm.containment_action.trim().length < 2) return ElMessage.warning("请填写临时遏制措施"); await saveExceptionAction(() => saveSpcContainment(selectedException.value!.id, { containment_action: containmentForm.containment_action.trim() }), "临时遏制已完成"); }
async function saveRootCause() { if (!selectedException.value || rootCauseForm.root_cause.trim().length < 2) return ElMessage.warning("请填写根因分析"); await saveExceptionAction(() => saveSpcRootCause(selectedException.value!.id, { root_cause: rootCauseForm.root_cause.trim() }), "根因分析已完成"); }
async function addSpcAction() { if (!selectedException.value || actionForm.description.trim().length < 2 || !actionForm.owner_id || !actionForm.due_date) return ElMessage.warning("请填写措施、责任人和期限"); await saveExceptionAction(() => createSpcAction(selectedException.value!.id, { ...actionForm, description: actionForm.description.trim() }), "CAPA 措施已创建"); }
async function completeSpcActionForm(actionId: string) { const evidence = completionEvidence[actionId]?.trim() || ""; if (!selectedException.value || evidence.length < 2) return ElMessage.warning("请填写完成证据"); const saved = await saveExceptionAction(() => completeSpcAction(selectedException.value!.id, actionId, { completion_evidence: evidence }), "CAPA 措施已完成"); if (saved) delete completionEvidence[actionId]; }
async function retestException() { if (!selectedException.value) return; if (retestForm.sample_value === null || !Number.isFinite(retestForm.sample_value)) return ElMessage.warning("请填写整改后的实际复验样本值"); await saveExceptionAction(() => retestSpcException(selectedException.value!.id, { sample_value: retestForm.sample_value }), "复验样本已录入"); }
async function closeException() { if (!selectedException.value || closeForm.evidence.trim().length < 2) return ElMessage.warning("请填写关闭证据"); const result = await saveExceptionAction(() => closeSpcException(selectedException.value!.id, { closure_evidence: closeForm.evidence.trim() }), "SPC 异常已关闭"); if (result?.status === "closed" && selectedException.value) selectedException.value = { ...selectedException.value, ...result, status: "closed" }; }
async function resumeException() { if (!selectedException.value) return; await saveExceptionAction(() => resumeSpcException(selectedException.value!.id), "异常已重新进入整改"); }
async function saveSupplierForm() { if (!supplierForm.supplier_id || !/^\d{4}-\d{2}$/.test(supplierForm.period)) return ElMessage.warning("请选择供应商并填写有效期间"); await saveAction(() => saveSupplierQuality({ supplier_id: supplierForm.supplier_id, period: supplierForm.period, note: supplierForm.note }), "采购检验已汇总，记录进入待审核"); }
function openSupplierReview(row: Row, action: "approve" | "reject") { selectedSupplier.value = row; supplierReviewAction.value = action; supplierReviewComment.value = ""; supplierReviewVisible.value = true; }
async function reviewSupplier() { if (!selectedSupplier.value) return; if (supplierReviewAction.value === "reject" && supplierReviewComment.value.trim().length < 2) return ElMessage.warning("驳回时请填写原因"); saving.value = true; try { const response = supplierReviewAction.value === "approve" ? await approveSupplierQuality(selectedSupplier.value.id, supplierReviewComment.value.trim()) : await rejectSupplierQuality(selectedSupplier.value.id, supplierReviewComment.value.trim()); unwrap(response); ElMessage.success(supplierReviewAction.value === "approve" ? "供应商质量已审核，并已联动供应商绩效" : "供应商质量已驳回"); supplierReviewVisible.value = false; await load(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "供应商质量审核失败"); } finally { saving.value = false; } }
async function openSupplierSources(row: Row) { selectedSupplier.value = row; supplierSourcesLoading.value = true; try { supplierSources.value = unwrap(await listSupplierQualitySources(row.id)) || []; supplierSourcesVisible.value = true; } catch (error) { ElMessage.error(error instanceof Error ? error.message : "来源检验加载失败"); } finally { supplierSourcesLoading.value = false; } }
async function saveCostForm() { if (!/^\d{4}-\d{2}$/.test(costForm.period)) return ElMessage.warning("请选择成本月份"); if (!costForm.cost_type) return ElMessage.warning("请选择成本类型"); if (costForm.source_type && !costForm.source_id.trim()) return ElMessage.warning("请选择来源类型后填写来源单据 ID"); if (costForm.amount < 0) return ElMessage.warning("质量成本不能为负数"); await saveAction(() => createQualityCost(costForm), "质量成本已保存"); }
async function confirmCost(row: Row) { try { const result = await ElMessageBox.prompt("可保留系统估算值，也可调整为实际金额。", "确认质量成本", { inputValue: String(row.amount || "0"), inputPattern: /^\d+(\.\d{1,2})?$/, inputErrorMessage: "请输入非负金额，最多保留两位小数", confirmButtonText: "确认", cancelButtonText: "取消" }); saving.value = true; unwrap(await confirmQualityCost(String(row.id), { amount: result.value })); ElMessage.success("质量成本已确认"); await load(); } catch (error) { if (error !== "cancel" && error !== "close") ElMessage.error(error instanceof Error ? error.message : "质量成本确认失败"); } finally { saving.value = false; } }
async function saveClaimForm() { if (!claimForm.customer_id || !claimForm.source_type || !claimForm.source_id || !claimForm.title) return ElMessage.warning("请选择客户、来源单据并填写索赔标题"); await saveAction(() => createCustomerClaim(claimForm), "客户质量索赔已创建，等待调查"); }
function openClaimWorkflow(row: Row, action: string) { selectedClaim.value = row; Object.assign(claimWorkflowForm, { action, owner_id: row.owner_id || users.value[0]?.value || "", due_date: row.due_date || new Date().toISOString().slice(0, 10), root_cause: row.root_cause || "", resolution: row.resolution || "", review_evidence: row.review_evidence || "", review_comment: "", approved_amount: Number(row.approved_amount || row.amount || 0), closure_evidence: row.closure_evidence || "" }); claimWorkflowVisible.value = true; }
async function submitClaimWorkflow() { if (!selectedClaim.value) return; const action = claimWorkflowForm.action; const payload: Row = { status: action, owner_id: claimWorkflowForm.owner_id, due_date: claimWorkflowForm.due_date, root_cause: claimWorkflowForm.root_cause.trim(), resolution: claimWorkflowForm.resolution.trim(), review_evidence: claimWorkflowForm.review_evidence.trim(), review_comment: claimWorkflowForm.review_comment.trim(), approved_amount: claimWorkflowForm.approved_amount, closure_evidence: claimWorkflowForm.closure_evidence.trim() }; saving.value = true; try { unwrap(await transitionCustomerClaim(selectedClaim.value.id, payload)); ElMessage.success(action === "investigating" ? "索赔已进入调查" : action === "pending_review" ? "索赔已提交审核" : action === "approved" ? "索赔已审核，财务费用单已生成" : action === "rejected" ? "索赔已驳回" : "索赔已关闭"); claimWorkflowVisible.value = false; await load(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "索赔流程操作失败"); } finally { saving.value = false; } }
onMounted(() => Promise.all([load(), loadOptions(["customers", "suppliers", "materials"]) ]));
</script>
<template>
  <section class="page-stack"><header class="page-heading"><div><small>QUALITY / ANALYTICS</small><h1>质量分析与索赔中心</h1><p>把 SPC 样本、供应商质量、质量成本和客户索赔统一到检验与 CAPA 证据链。</p></div><el-button :loading="loading" @click="load">刷新</el-button></header>
    <el-tabs v-model="activeTab" type="border-card">
      <el-tab-pane label="SPC 控制" name="spc"><div class="toolbar"><el-select v-model="spcForm.material_id" filterable clearable placeholder="选择物料并搜索" style="width: 220px"><el-option v-for="item in materials" :key="item.value" v-bind="item" /></el-select><el-input v-model="spcForm.metric" placeholder="检测指标（手动输入）" /><el-input-number v-model="spcForm.sample_value" placeholder="样本值" /><el-input-number v-model="spcForm.lsl" placeholder="LSL" /><el-input-number v-model="spcForm.usl" placeholder="USL" /><el-button type="primary" @click="saveSpcForm">记录样本</el-button></div><el-alert class="spc-flow-hint" type="info" :closable="false" title="录入样本后自动判定控制状态；失控样本会进入异常确认 → 遏制 → 根因 → CAPA → 复验 → 关闭闭环。" /><el-table :data="spcRows" stripe><el-table-column label="物料"><template #default="scope">{{ materialLabel(scope.row.material_id) }}</template></el-table-column><el-table-column prop="metric" label="指标" /><el-table-column prop="sample_value" label="样本值" /><el-table-column prop="lsl" label="LSL" /><el-table-column prop="usl" label="USL" /><el-table-column prop="cpk" label="Cpk" /><el-table-column label="控制状态"><template #default="scope"><el-tag class="control-status-tag" :type="controlStatusTagType(scope.row.control_status || scope.row.status)" effect="light">{{ controlStatusLabel(scope.row.control_status || scope.row.status) }}</el-tag></template></el-table-column><el-table-column label="异常流程"><template #default="scope"><el-tag v-if="scope.row.workflow_status && scope.row.workflow_status !== 'normal'" :type="workflowStatusTagType(scope.row.workflow_status)" effect="light">{{ workflowStatusLabel(scope.row.workflow_status) }}</el-tag><span v-else class="muted">正常监控</span></template></el-table-column><el-table-column label="操作" width="120"><template #default="scope"><el-button v-if="scope.row.exception && scope.row.exception.status !== 'closed'" link type="primary" @click="openSpcException(scope.row)">处理异常</el-button><span v-else-if="!scope.row.exception" class="muted">—</span></template></el-table-column></el-table><ClientPagination v-model:page="spcPage" v-model:page-size="spcPageSize" :total="spcTotal" @update:page-size="updateSpcPageSize" /></el-tab-pane>
      <el-tab-pane label="供应商质量" name="supplier">
        <div class="toolbar"><el-button type="primary" @click="open('supplier')">汇总采购检验</el-button><span class="quality-rule-hint">评分规则：100 - 缺陷率×100 - 严重不合格×10 - 主要不合格×3 - 一般不合格×1</span></div>
        <el-table class="supplier-quality-table" :data="supplierQualityRows" stripe border>
          <el-table-column label="供应商"><template #default="scope">{{ supplierLabel(scope.row.supplier_id) }}</template></el-table-column><el-table-column prop="period" label="期间" /><el-table-column prop="inspection_count" label="检验数" /><el-table-column prop="defect_count" label="缺陷数" /><el-table-column label="缺陷率"><template #default="scope">{{ defectRateLabel(scope.row.defect_rate) }}</template></el-table-column><el-table-column prop="score" label="质量得分" /><el-table-column label="状态"><template #default="scope"><el-tag class="supplier-quality-status" :type="tagTypeOf(scope.row.status)" effect="light">{{ statusLabel(scope.row.status) }}</el-tag></template></el-table-column><el-table-column label="CAPA"><template #default="scope"><el-tag class="supplier-quality-status" :type="capaStatusTagType(scope.row.capa_status)" effect="light">{{ capaStatusLabel(scope.row.capa_status) }}</el-tag></template></el-table-column>
          <el-table-column label="汇总来源" min-width="150"><template #default="scope"><el-tag :type="scope.row.source_available ? 'success' : 'info'" effect="light">{{ scope.row.source_available ? aggregationSourceLabel(scope.row.aggregation_source) : '无可追溯来源' }}</el-tag></template></el-table-column>
          <el-table-column label="操作" width="260"><template #default="scope"><el-button v-if="scope.row.source_available" link type="primary" @click="openSupplierSources(scope.row)">来源明细</el-button><span v-else class="muted">无采购检验来源</span><el-button v-if="scope.row.status === 'submitted'" link type="success" @click="openSupplierReview(scope.row, 'approve')">审核</el-button><el-button v-if="scope.row.status === 'submitted'" link type="danger" @click="openSupplierReview(scope.row, 'reject')">驳回</el-button></template></el-table-column>
          <template #empty><el-empty description="暂无供应商质量汇总" /></template>
        </el-table><ClientPagination v-model:page="supplierQualityPage" v-model:page-size="supplierQualityPageSize" :total="supplierQualityTotal" @update:page-size="updateSupplierQualityPageSize" />
      </el-tab-pane>
      <el-tab-pane label="质量成本" name="cost"><div class="toolbar"><el-date-picker v-model="costForm.period" type="month" value-format="YYYY-MM" format="YYYY-MM" placeholder="选择月份" /><el-select v-model="costForm.cost_type" placeholder="成本类型"><el-option label="预防成本" value="prevention" /><el-option label="鉴定成本" value="appraisal" /><el-option label="内部失败成本" value="internal_failure" /><el-option label="外部失败成本" value="external_failure" /></el-select><el-input-number v-model="costForm.amount" :min="0" /><el-select v-model="costForm.source_type" clearable placeholder="来源类型"><el-option v-for="(label, value) in qualityCostSourceTypeLabels" :key="value" :label="label" :value="value" /></el-select><el-input v-if="costForm.source_type" v-model="costForm.source_id" placeholder="来源单据 ID" /><el-input v-model="costForm.note" placeholder="备注" /><el-button type="primary" @click="saveCostForm">记录成本</el-button></div><el-table :data="costRows" stripe><el-table-column prop="period" label="期间" /><el-table-column label="成本类型"><template #default="scope">{{ qualityCostTypeLabel(scope.row.cost_type) }}</template></el-table-column><el-table-column prop="amount" label="金额" /><el-table-column label="状态"><template #default="scope">{{ qualityCostStatusLabel(scope.row.status) }}</template></el-table-column><el-table-column label="来源类型"><template #default="scope">{{ qualityCostSourceTypeLabel(scope.row.source_type) }}</template></el-table-column><el-table-column label="来源"><template #default="scope">{{ scope.row.source_label || scope.row.source_id || '手工录入' }}</template></el-table-column><el-table-column prop="note" label="备注" /><el-table-column label="操作" width="100"><template #default="scope"><el-button v-if="scope.row.status === 'estimated'" link type="success" @click="confirmCost(scope.row)">确认</el-button></template></el-table-column></el-table><ClientPagination v-model:page="costPage" v-model:page-size="costPageSize" :total="costTotal" /></el-tab-pane>
      <el-tab-pane label="客户质量索赔" name="claims"><div class="toolbar"><el-button type="primary" @click="open('claim')">新建索赔</el-button><span class="quality-rule-hint">流程：待处理 → 调查中 → 待审核 → 已审核/已驳回 → 已关闭</span></div><el-table class="customer-claim-table" :data="claimRows" stripe border><el-table-column prop="claim_no" label="索赔单号" /><el-table-column label="客户"><template #default="scope">{{ scope.row.customer_name || customerLabel(scope.row.customer_id) }}</template></el-table-column><el-table-column prop="title" label="标题" /><el-table-column label="来源"><template #default="scope"><span>{{ claimSourceTypeLabel(scope.row.source_type) }} · {{ scope.row.source_document_name }}</span></template></el-table-column><el-table-column label="金额"><template #default="scope">{{ scope.row.approved_amount || scope.row.amount }}</template></el-table-column><el-table-column label="状态"><template #default="scope"><el-tag class="customer-claim-status" :type="tagTypeOf(scope.row.status)" effect="light">{{ statusLabel(scope.row.status) }}</el-tag></template></el-table-column><el-table-column label="财务"><template #default="scope"><el-tag v-if="scope.row.finance_expense_status" type="info" effect="light">{{ financeExpenseStatusLabel(scope.row.finance_expense_status) }}</el-tag><span v-else class="muted">未生成</span></template></el-table-column><el-table-column label="操作" width="300"><template #default="scope"><el-button v-if="scope.row.status === 'open'" link type="primary" @click="openClaimWorkflow(scope.row, 'investigating')">开始调查</el-button><el-button v-if="scope.row.status === 'investigating'" link type="primary" @click="openClaimWorkflow(scope.row, 'pending_review')">提交审核</el-button><el-button v-if="scope.row.status === 'pending_review'" link type="success" @click="openClaimWorkflow(scope.row, 'approved')">审核通过</el-button><el-button v-if="scope.row.status === 'pending_review'" link type="danger" @click="openClaimWorkflow(scope.row, 'rejected')">驳回</el-button><el-button v-if="scope.row.status === 'rejected'" link type="warning" @click="openClaimWorkflow(scope.row, 'investigating')">重新调查</el-button><el-button v-if="scope.row.status === 'approved'" link type="success" @click="openClaimWorkflow(scope.row, 'closed')">验证关闭</el-button></template></el-table-column></el-table><ClientPagination v-model:page="claimPage" v-model:page-size="claimPageSize" :total="claimTotal" @update:page-size="updateClaimPageSize" /></el-tab-pane>
    </el-tabs>
    <el-dialog :model-value="dialog === 'supplier'" title="汇总采购检验" width="560px" @update:model-value="(value: boolean) => { if (!value) dialog = ''; }"><el-alert title="系统将自动读取本期间已提交/已关闭的来料检验及其不合格记录，计算缺陷率和质量得分。" type="info" :closable="false" /><el-form label-width="100px" class="supplier-quality-form"><el-form-item label="供应商" required><el-select v-model="supplierForm.supplier_id" filterable><el-option v-for="item in suppliers" :key="item.value" v-bind="item" /></el-select></el-form-item><el-form-item label="期间" required><el-input v-model="supplierForm.period" placeholder="YYYY-MM" /></el-form-item><el-form-item label="备注"><el-input v-model="supplierForm.note" type="textarea" :rows="2" /></el-form-item></el-form><template #footer><el-button @click="dialog = ''">取消</el-button><el-button type="primary" :loading="saving" @click="saveSupplierForm">汇总并提交审核</el-button></template></el-dialog>
    <el-dialog v-model="supplierReviewVisible" :title="supplierReviewAction === 'approve' ? '审核供应商质量' : '驳回供应商质量'" width="520px"><el-alert v-if="selectedSupplier" :title="`${supplierLabel(selectedSupplier.supplier_id)} · ${selectedSupplier.period} · 得分 ${selectedSupplier.score}`" type="info" :closable="false" /><el-form label-width="90px"><el-form-item :label="supplierReviewAction === 'approve' ? '审核意见' : '驳回原因'" :required="supplierReviewAction === 'reject'"><el-input v-model="supplierReviewComment" type="textarea" :rows="3" /></el-form-item></el-form><template #footer><el-button @click="supplierReviewVisible = false">取消</el-button><el-button :type="supplierReviewAction === 'approve' ? 'success' : 'danger'" :loading="saving" @click="reviewSupplier">{{ supplierReviewAction === 'approve' ? '确认审核' : '确认驳回' }}</el-button></template></el-dialog>
    <el-dialog v-model="supplierSourcesVisible" title="供应商质量来源明细" width="760px"><el-table v-loading="supplierSourcesLoading" :data="supplierSources" stripe border><el-table-column prop="doc_no" label="来源单据" /><el-table-column label="来源类型"><template #default="scope">{{ scope.row.source_type === 'purchase_receipt' ? '采购入库' : '采购订单' }}</template></el-table-column><el-table-column prop="inspection_status" label="检验状态" /><el-table-column prop="inspection_result" label="检验结果" /><el-table-column label="不合格"><template #default="scope"><el-tag v-if="scope.row.nonconformance" type="danger">{{ scope.row.nonconformance.severity }} / {{ scope.row.nonconformance.status }}</el-tag><span v-else class="muted">无</span></template></el-table-column><template #empty><el-empty description="暂无可展示的来源快照" /></template></el-table></el-dialog>
    <el-dialog :model-value="dialog === 'claim'" title="新建客户质量索赔" width="560px" @update:model-value="(value: boolean) => { if (!value) dialog = ''; }"><el-form label-width="90px"><el-form-item label="客户" required><el-select v-model="claimForm.customer_id" filterable @change="loadClaimSources"><el-option v-for="item in customers" :key="item.value" v-bind="item" /></el-select></el-form-item><el-form-item label="来源类型" required><el-select v-model="claimForm.source_type" @change="() => { claimForm.source_id = ''; loadClaimSources(); }"><el-option v-for="(label, value) in claimSourceTypeLabels" :key="value" :label="label" :value="value" /></el-select></el-form-item><el-form-item label="来源单据" required><el-select v-model="claimForm.source_id" filterable :loading="claimSourcesLoading" placeholder="请选择真实来源单据"><el-option v-for="item in claimSources" :key="item.source_id" :label="item.label" :value="item.source_id" /></el-select></el-form-item><el-form-item label="索赔标题" required><el-input v-model="claimForm.title" /></el-form-item><el-form-item label="索赔金额"><el-input-number v-model="claimForm.amount" :min="0" :precision="2" /></el-form-item></el-form><template #footer><el-button @click="dialog = ''">取消</el-button><el-button type="primary" :loading="saving" @click="saveClaimForm">创建</el-button></template></el-dialog>
    <el-dialog v-model="claimWorkflowVisible" :title="selectedClaim ? `客户质量索赔 · ${statusLabel(claimWorkflowForm.action)}` : '客户质量索赔闭环'" width="620px"><el-alert v-if="selectedClaim" :title="`${selectedClaim.claim_no} · ${selectedClaim.customer_name || customerLabel(selectedClaim.customer_id)} · ${selectedClaim.source_document_name || '-'}`" type="info" :closable="false" /><el-form label-width="100px" class="claim-workflow-form"><template v-if="claimWorkflowForm.action === 'investigating'"><el-form-item label="责任人" required><el-select v-model="claimWorkflowForm.owner_id" filterable><el-option v-for="item in ownerOptions()" :key="item.value" v-bind="item" /></el-select></el-form-item><el-form-item label="整改期限" required><el-date-picker v-model="claimWorkflowForm.due_date" type="date" value-format="YYYY-MM-DD" /></el-form-item></template><template v-if="claimWorkflowForm.action === 'pending_review'"><el-form-item label="根因分析" required><el-input v-model="claimWorkflowForm.root_cause" type="textarea" :rows="3" /></el-form-item><el-form-item label="整改方案" required><el-input v-model="claimWorkflowForm.resolution" type="textarea" :rows="3" /></el-form-item><el-form-item label="审核证据" required><el-input v-model="claimWorkflowForm.review_evidence" type="textarea" :rows="3" placeholder="客户反馈、检验报告、整改验证等" /></el-form-item></template><template v-if="claimWorkflowForm.action === 'approved' || claimWorkflowForm.action === 'rejected'"><el-form-item v-if="claimWorkflowForm.action === 'approved'" label="审核金额" required><el-input-number v-model="claimWorkflowForm.approved_amount" :min="0" :precision="2" /></el-form-item><el-form-item :label="claimWorkflowForm.action === 'approved' ? '审核意见' : '驳回原因'" :required="claimWorkflowForm.action === 'rejected'"><el-input v-model="claimWorkflowForm.review_comment" type="textarea" :rows="3" /></el-form-item></template><template v-if="claimWorkflowForm.action === 'closed'"><el-form-item label="关联 NCR"><el-tag :type="selectedClaim?.ncr_status === 'closed' ? 'success' : 'warning'" effect="light">{{ selectedClaim?.nonconformance_id ? `NCR ${statusLabel(selectedClaim.ncr_status)}` : '未关联 NCR' }}</el-tag></el-form-item><el-form-item label="关闭证据" required><el-input v-model="claimWorkflowForm.closure_evidence" type="textarea" :rows="3" placeholder="客户确认、整改验证或财务处理依据" /></el-form-item></template></el-form><template #footer><el-button @click="claimWorkflowVisible = false">取消</el-button><el-button :type="claimWorkflowForm.action === 'rejected' ? 'danger' : 'primary'" :loading="saving" @click="submitClaimWorkflow">确认{{ claimWorkflowForm.action === 'rejected' ? '驳回' : claimWorkflowForm.action === 'approved' ? '审核' : claimWorkflowForm.action === 'closed' ? '关闭' : claimWorkflowForm.action === 'pending_review' ? '提交审核' : '调查' }}</el-button></template></el-dialog>
      <el-dialog v-if="selectedException" v-model="exceptionDialog" class="spc-exception-dialog" title="SPC 异常闭环" width="760px"><div class="exception-summary"><span>{{ materialLabel(selectedException.material_id) }}</span><span>{{ selectedException.metric }}</span><el-tag type="danger">{{ controlStatusLabel(selectedException.control_status) }}</el-tag><el-tag :type="workflowStatusTagType(selectedException.status)">{{ workflowStatusLabel(selectedException.status) }}</el-tag></div><el-steps :active="Math.min(Math.max(['pending_review','containment','root_cause','corrective_action','retest','closed'].indexOf(selectedException.status), 0), 5)" finish-status="success" simple><el-step title="确认" /><el-step title="遏制" /><el-step title="根因" /><el-step title="CAPA" /><el-step title="复验" /><el-step title="关闭" /></el-steps><div v-if="selectedException.status === 'pending_review'" class="workflow-panel"><el-form label-width="100px"><el-form-item label="责任人" required><el-select v-model="confirmForm.owner_id" filterable><el-option v-for="item in ownerOptions()" :key="item.value" v-bind="item" /></el-select></el-form-item><el-form-item label="整改期限" required><el-date-picker v-model="confirmForm.due_date" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="严重程度"><el-select v-model="confirmForm.severity"><el-option label="一般" value="minor" /><el-option label="重大" value="major" /><el-option label="严重" value="critical" /></el-select></el-form-item></el-form><el-button type="primary" :loading="saving" @click="confirmException">确认异常</el-button></div><div v-else-if="selectedException.status === 'containment'" class="workflow-panel"><el-form label-width="100px"><el-form-item label="临时遏制措施" required><el-input v-model="containmentForm.containment_action" type="textarea" :rows="4" placeholder="隔离批次、暂停放行、追加抽检等" /></el-form-item></el-form><el-button type="primary" :loading="saving" @click="saveContainment">保存并进入原因分析</el-button></div><div v-else-if="selectedException.status === 'root_cause'" class="workflow-panel"><el-form label-width="100px"><el-form-item label="根因分析" required><el-input v-model="rootCauseForm.root_cause" type="textarea" :rows="4" placeholder="填写可验证的发生原因和流出原因" /></el-form-item></el-form><el-button type="primary" :loading="saving" @click="saveRootCause">保存根因并制定 CAPA</el-button></div><div v-else-if="selectedException.status === 'corrective_action' || selectedException.status === 'reopened'" class="workflow-panel"><el-alert v-if="selectedException.status === 'reopened'" title="复验未通过，请继续整改后重新复验" type="warning" :closable="false" /><el-button v-if="selectedException.status === 'reopened'" type="warning" @click="resumeException">进入整改</el-button><el-divider content-position="left">CAPA 措施</el-divider><el-form inline class="capa-form"><el-form-item label="类型"><el-select v-model="actionForm.action_type"><el-option label="纠正措施" value="corrective" /><el-option label="预防措施" value="preventive" /></el-select></el-form-item><el-form-item label="措施"><el-input v-model="actionForm.description" placeholder="措施内容" /></el-form-item><el-form-item label="责任人"><el-select v-model="actionForm.owner_id" filterable><el-option v-for="item in ownerOptions()" :key="item.value" v-bind="item" /></el-select></el-form-item><el-form-item label="期限"><el-date-picker v-model="actionForm.due_date" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-button type="primary" :loading="saving" @click="addSpcAction">新增措施</el-button></el-form><el-table :data="selectedException.actions || []" size="small"><el-table-column prop="action_type" label="类型"><template #default="scope">{{ scope.row.action_type === 'corrective' ? '纠正措施' : '预防措施' }}</template></el-table-column><el-table-column prop="description" label="措施" /><el-table-column prop="status" label="状态"><template #default="scope">{{ scope.row.status === 'completed' ? '已完成' : '待完成' }}</template></el-table-column><el-table-column label="完成证据"><template #default="scope"><el-input v-if="scope.row.status !== 'completed'" v-model="completionEvidence[String(scope.row.id)]" placeholder="填写证据" /><span v-else>{{ scope.row.completion_evidence || '—' }}</span></template></el-table-column><el-table-column label="操作" width="100"><template #default="scope"><el-button v-if="scope.row.status !== 'completed'" link type="success" @click="completeSpcActionForm(String(scope.row.id))">完成</el-button></template></el-table-column></el-table><el-form inline class="retest-form"><el-form-item label="复验样本值" required><el-input-number v-model="retestForm.sample_value" placeholder="填写实际测量值" /></el-form-item><el-button class="next-action" type="primary" :loading="saving" @click="retestException">发起复验</el-button></el-form></div><div v-else-if="selectedException.status === 'retest'" class="workflow-panel"><el-alert title="复验已通过，请填写关闭证据。" type="success" :closable="false" /><el-form label-width="100px"><el-form-item label="关闭证据"><el-input v-model="closeForm.evidence" type="textarea" :rows="3" placeholder="复验报告、放行记录或验证结论" /></el-form-item></el-form><el-button type="success" :loading="saving" @click="closeException">关闭异常</el-button></div><div v-else-if="selectedException.status === 'closed'" class="workflow-panel"><el-alert title="该 SPC 异常已完成闭环" type="success" :closable="false" /><p class="muted">关闭证据：{{ selectedException.closure_evidence || '—' }}</p></div></el-dialog>
  </section>
</template>
