ider{margin-top:4px}.capa-form{display:grid !important;grid-template-columns:minmax(150px,1fr) minmax(250px,1.6fr) auto;grid-template-areas:"type measure spacer" "owner due add";gap:10px 8px;align-items:end}.capa-form :deep(.el-form-item){width:100%;min-width:0;margin:0}.capa-form :deep(.el-form-item:nth-child(1)){grid-area:type}.capa-form :deep(.el-form-item:nth-child(2)){grid-area:measure}.capa-form :deep(.el-form-item:nth-child(3)){grid-area:owner}.capa-form :deep(.el-form-item:nth-child(4)){grid-area:due}.capa-form :deep(.el-form-item__label){width:50px !important;padding-right:8px}.capa-form :deep(.el-form-item__content){min-width:0;flex:1}.capa-form :deep(.el-select),.capa-form :deep(.el-input),.capa-form :deep(.el-date-editor){width:100% !important}.capa-form > .el-button{grid-area:add;align-self:end;margin:0;white-space:nowrap}.retest-form{display:flex;align-items:flex-end;width:100%;margin-top:18px}.retest-form :deep(.el-form-item){margin-bottom:0}.retest-form :deep(.el-input-number){width:220px}.retest-form .next-action{margin:0 0 0 auto}.next-action{margin-top:16px}.exception-summary :deep(.el-tag){font-weight:700}@media (max-width:900px){.capa-form{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-areas:"type measure" "owner due" "add add"}.capa-form > .el-button{justify-self:end}}</style>
